// One clean item per incoming WhatsApp message. Status updates (sent, delivered, read) are dropped here.
const out = [];
$input.all().forEach((item, index) => {
  const raw = item.json;
  const v = raw.messages ? raw : (raw.entry?.[0]?.changes?.[0]?.value ?? raw);
  const msg = v.messages?.[0];
  if (!msg) return;

  const contacto = v.contacts?.[0] ?? {};
  let tipo = msg.type;
  let texto = '';
  let eleccion = null;

  if (msg.type === 'text') texto = msg.text?.body ?? '';
  else if (msg.type === 'interactive') {
    const r = msg.interactive?.button_reply ?? msg.interactive?.list_reply ?? {};
    texto = r.title ?? '';
    // our time buttons carry the appointment in their id: {"i": inicio, "u": urgente, "m": motivo, "n": nombre}
    try {
      const p = JSON.parse(r.id);
      if (p && p.i) { eleccion = p; tipo = 'eleccion'; }
    } catch (e) {}
  } else if (msg.type === 'button') {
    // quick reply on a template: the only template with buttons is the appointment reminder
    texto = `${msg.button?.text ?? ''} (respuesta al recordatorio de su cita de mañana)`;
  } else if (msg.type !== 'audio') texto = `[El paciente envió un mensaje de tipo "${msg.type}" que no se puede leer]`;

  out.push({
    json: {
      tipo,
      texto,
      telefono: msg.from,
      nombre: eleccion?.n || contacto.profile?.name || '',
      audioId: msg.audio?.id ?? null,
      mensajeId: msg.id,
      phoneNumberId: v.metadata?.phone_number_id,
      // only for a tapped time button
      inicio: eleccion?.i ?? null,
      urgente: eleccion ? eleccion.u === 1 : false,
      motivo: eleccion?.m ?? '',
    },
    pairedItem: { item: index },
  });
});
return out;

