// Turns the agent's answer into what WhatsApp needs, plus the conversation context.
const ctx = $('Lee el mensaje').item.json;
const o = $json.output ?? {};
// The agent failed (API down, no credits...): answer politely and alert the clinic.
const fallo = !$json.output;
const corta = (s, n) => String(s ?? '').replace(/\s+/g, ' ').trim().slice(0, n);

let original = ctx.texto;
try { original = $('Transcribe audio').item.json.text || original; } catch (e) {}

const nombre = corta(o.nombre_paciente || ctx.nombre, 40);
const urgente = o.urgente === true;
const motivo = corta(o.motivo, 40);

// WhatsApp reply buttons: max 3, unique titles up to 20 characters, ids up to 256 characters
const vistos = new Set();
const botones = (Array.isArray(o.botones) ? o.botones : [])
  .filter((b) => b && b.inicio && b.titulo && !vistos.has(corta(b.titulo, 20)) && vistos.add(corta(b.titulo, 20)))
  .slice(0, 3)
  .map((b) => ({
    type: 'reply',
    reply: { id: JSON.stringify({ i: b.inicio, u: urgente ? 1 : 0, m: motivo, n: nombre }).slice(0, 256), title: corta(b.titulo, 20) },
  }));

let accion = fallo ? 'derivar' : o.accion || 'responder';
if (accion === 'ofrecer_horarios' && botones.length === 0) accion = 'responder';
if (accion === 'reservar' && !DateTime.fromISO(String(o.cita_inicio ?? '')).isValid) accion = 'responder';

return {
  json: {
    accion,
    respuesta: o.respuesta || 'Gracias por escribir 🙏 En cuanto pueda, alguien de la clínica te responde por aquí.',
    botones,
    urgente,
    motivo,
    nombre,
    inicio: o.cita_inicio ?? null,
    telefono: ctx.telefono,
    phoneNumberId: ctx.phoneNumberId,
    mensajeOriginal: corta(original, 180),
  },
};

