// Patients booked in the last 24 hours, as one line (WhatsApp template parameters can't contain line breaks).
const cfg = $('Datos de la clínica (mañana)').first().json;
const desde = $now.minus({ hours: 24 });
const filas = $input.all()
  .map((i) => i.json)
  .filter((r) => r.Registrado && DateTime.fromISO(r.Registrado) >= desde)
  .sort((a, b) => String(a.Cita).localeCompare(String(b.Cita)));
if (filas.length === 0) return [];
const lista = filas
  .map((r) => {
    const hora = DateTime.fromISO(r.Cita, { setZone: true }).setZone(cfg.zonaHoraria).setLocale('es').toFormat("ccc HH:mm");
    return `${hora} ${r.Nombre} (${String(r.Motivo).toLowerCase()}${r.Urgente === 'Sí' ? ', urgencia' : ''})`;
  })
  .join(' · ');
return [{ json: { total: String(filas.length), lista } }];

// One reminder per appointment booked by the receptionist (it writes "WhatsApp: +<number>" in the description).
const cfg = $('Datos de la clínica (mañana)').first().json;
const out = [];
for (const { json: ev } of $input.all()) {
  const tel = String(ev.description ?? '').match(/WhatsApp:\s*\+?(\d{8,15})/);
  if (!tel || !ev.start?.dateTime) continue;
  const nombre = (String(ev.description).match(/Paciente:\s*(.+)/) ?? [])[1] ?? 'Hola';
  const hora = DateTime.fromISO(ev.start.dateTime, { setZone: true }).setZone(cfg.zonaHoraria).toFormat('HH:mm');
  out.push({ json: { telefono: tel[1], nombre: nombre.trim(), hora } });
}
return out;

// Whisper detects the format from the file extension, and WhatsApp's download has none.
// Voice notes arrive as OGG; attached audio files can be MP3, M4A, WAV or WEBM.
const extensiones = {
  'audio/ogg': 'ogg', 'audio/opus': 'ogg', 'audio/mpeg': 'mp3', 'audio/mp3': 'mp3',
  'audio/mp4': 'm4a', 'audio/m4a': 'm4a', 'audio/x-m4a': 'm4a', 'audio/aac': 'm4a',
  'audio/wav': 'wav', 'audio/x-wav': 'wav', 'audio/webm': 'webm',
};
for (const item of $input.all()) {
  const audio = item.binary?.data;
  if (!audio) continue;
  const tipo = String(audio.mimeType ?? '').split(';')[0].trim().toLowerCase();
  const ext = extensiones[tipo] ?? 'ogg';
  audio.fileName = `nota-de-voz.${ext}`;
  audio.fileExtension = ext;
}
return $input.all();
